package got.wildlife; import got.GOTItems; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.level.Level; public final class GOTShadowcatEntity extends GOTDefensiveAnimalEntity { public GOTShadowcatEntity(EntityType<? extends net.minecraft.world.entity.animal.Animal> t,Level l){super(t,l);xpReward=7;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,50).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.ATTACK_DAMAGE,5).add(Attributes.FOLLOW_RANGE,28);} @Override public boolean canFreeze(){return false;} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(GOTItems.FUR.get());} }